'use strict';
const $=selector=>document.querySelector(selector);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mentorDismissTimer=null;
let token=sessionStorage.getItem('adapta_v6_token')||'';
let role=sessionStorage.getItem('adapta_v6_role')||'';
let page='dashboard',overview=null,active=null,feedback=null,timerHandle=null,submitting=false,authRole='student',topicFilter='',kindFilter='',tutorTopic='Oferta y demanda',enrollmentList=[],timerWarningSent=false,answerEditTimer=null;
const TOPICS=['Oferta y demanda','Elasticidad','Teoría del consumidor','Producción y costes','Competencia perfecta','Monopolio','Oligopolios','Competencia monopolística','Teoría de juegos'];
const lessons={
'Oferta y demanda':{idea:'El equilibrio surge cuando la cantidad que desean comprar los consumidores coincide con la que desean vender los productores.',steps:['Expresa la demanda y la oferta como funciones del precio.','Iguala las dos cantidades y despeja el precio.','Sustituye el precio para hallar la cantidad y comprueba ambas expresiones.'],error:'Confundir desplazamientos de la curva con movimientos sobre ella: un cambio del propio precio causa un movimiento, mientras que renta, tecnología y gustos pueden desplazar curvas.',example:'Si Qd=80−2P y Qs=20+P, entonces 80−2P=20+P; P=20 y Q=40.'},
'Elasticidad':{idea:'La elasticidad mide respuestas proporcionales. Su signo y magnitud orientan las decisiones de precios y permiten estudiar la incidencia de impuestos.',steps:['Identifica las variables y la variación relevante.','Aplica elasticidad puntual o arco según los datos.','Interpreta el valor absoluto: menor que 1, igual a 1 o mayor que 1.'],error:'Confundir pendiente y elasticidad. La pendiente lineal puede ser constante mientras la elasticidad puntual cambia.',example:'Si Q=100−2P, en P=20 la cantidad es 60 y la elasticidad puntual es −2·20/60=−0,67.'},
'Teoría del consumidor':{idea:'El consumidor elige una cesta para maximizar utilidad sin superar su presupuesto.',steps:['Plantea U(x,y) y px·x+py·y≤M.','En óptimo interior diferenciable, iguala UMx/UMy con px/py.','Comprueba gasto, no negatividad y posibles soluciones de esquina.'],error:'Suponer que siempre hay una solución interior. Con sustitutos perfectos o determinadas preferencias puede haber óptimos de esquina.',example:'Con U=x·y, M=120 y px=3, py=2, el consumidor gasta 60 en cada bien: x=20, y=30.'},
'Producción y costes':{idea:'La empresa transforma factores en producto y busca producir eficientemente. Los costes medios y marginales responden a preguntas distintas.',steps:['Diferencia costes fijos y variables.','Deriva CT para obtener CMg.','Divide CT entre Q para obtener CMeT y verifica la cantidad de producción.'],error:'Derivar CT/Q en vez de CT para calcular coste marginal. CMg se obtiene de la derivada de CT.',example:'Para CT=50+2Q+Q², CMg=2+2Q y CMeT=50/Q+2+Q.'},
'Competencia perfecta':{idea:'La empresa acepta el precio de mercado y elige cuánto producir, siempre considerando sus costes evitables a corto plazo.',steps:['Iguala P=CMg en la rama creciente si hay óptimo interior.','Comprueba si P cubre como mínimo el CVMe.','Calcula beneficio económico teniendo en cuenta el coste de oportunidad.'],error:'Olvidar la condición de cierre. Igualar precio y coste marginal no basta si P cae por debajo del CVMe mínimo.',example:'Con P=12 y CMg=2Q, Q=6; aún hay que comprobar que conviene operar.'},
'Monopolio':{idea:'El monopolista enfrenta una demanda decreciente y puede influir en el precio restringiendo la cantidad vendida.',steps:['Calcula el ingreso total IT=P(Q)·Q.','Deriva para obtener IMg y resuelve IMg=CMg.','Sustituye Q en la demanda inversa para hallar P.'],error:'Igualar P=CMg para un monopolista. En general se iguala IMg=CMg y luego se obtiene P desde la demanda.',example:'Si P=100−Q y CMg=20, IMg=100−2Q: Q*=40 y P*=60.'}
};
Object.assign(lessons,{
'Oligopolios':{idea:'En oligopolio las decisiones de cada empresa dependen de las de sus rivales.',steps:['Identifica las funciones de beneficio.','Obtén las mejores respuestas.','Resuelve simultáneamente las mejores respuestas para encontrar el equilibrio.'],error:'Confundir el equilibrio de Cournot en cantidades con el de Bertrand en precios.',example:'Con P=120−Q y coste marginal 30, en Cournot simétrico cada empresa produce (120−30)/3=30.'},
'Competencia monopolística':{idea:'Las empresas venden productos diferenciados y afrontan una demanda individual decreciente.',steps:['Calcula el ingreso marginal a partir de la demanda.','Iguala ingreso marginal y coste marginal a corto plazo.','Estudia el ajuste de entrada a largo plazo y el beneficio económico.'],error:'Confundir la diferenciación de producto con un monopolio sin entrada.',example:'Con P=80−Q y CMg=20, la cantidad óptima interior es Q=30.'},
'Teoría de juegos':{idea:'Las decisiones estratégicas se analizan considerando los incentivos y respuestas de otros jugadores.',steps:['Identifica jugadores, estrategias y pagos.','Busca la mejor respuesta de cada jugador ante cada estrategia rival.','Comprueba si hay equilibrio de Nash y si las estrategias son dominantes.'],error:'Confundir un resultado Pareto eficiente con un equilibrio de Nash.',example:'En un dilema del prisionero, la estrategia individual dominante puede llevar a un resultado conjunto peor.'}
});
async function request(url,{method='GET',body=null}={}){
  const res=await fetch(url,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});
  if(!res.ok){let detail='Error HTTP '+res.status;try{const j=await res.json();detail=j.detail||detail}catch{}if(res.status===401 && token){window.adaptaExpireIdleSession?.(detail)}throw Error(detail)}
  return res;
}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.tm);toast.tm=setTimeout(()=>t.classList.remove('show'),3400)}
function showAuth(){$('#auth').hidden=false;$('#app').hidden=true;$('#teacher').hidden=true;$('#mentorWidget').hidden=true;stopTimer()}
function saveSession(res){token=res.token;role=res.role;sessionStorage.setItem('adapta_v6_token',token);sessionStorage.setItem('adapta_v6_role',role);if(role==='student')window.adaptaIdleStart?.(true)}
function roleSelect(r){authRole=r;document.querySelectorAll('[data-authrole]').forEach(x=>x.classList.toggle('is-on',x.dataset.authrole===r));$('#student-fields').hidden=r!=='student';$('#teacher-fields').hidden=r!=='teacher';$('#login-error').textContent=''}
function initAuth(){document.querySelectorAll('[data-authrole]').forEach(b=>b.onclick=()=>roleSelect(b.dataset.authrole));$('#loginBtn').onclick=login;$('#accessPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#accessTeacher').addEventListener('keydown',e=>{if(e.key==='Enter')login()});}
async function login(){const b=$('#loginBtn');b.disabled=true;$('#login-error').textContent='';try{
const data=authRole==='teacher'?{password:$('#accessTeacher').value}:{code:$('#accessCode').value.trim(),password:$('#accessPassword').value,invitation:$('#accessInvite').value.trim()};
const res=await (await request('/api/'+(authRole==='teacher'?'teacher':'student')+'/login',{method:'POST',body:data})).json();saveSession(res);await enter();
}catch(e){$('#login-error').textContent=e.message}finally{b.disabled=false}}
async function enter(){let data=await(await request('/api/me')).json();$('#auth').hidden=true;
if(role==='teacher'){$('#app').hidden=true;$('#teacher').hidden=false;$('#mentorWidget').hidden=true;await renderTeacher();return}
$('#teacher').hidden=true;$('#app').hidden=false;$('#mentorWidget').hidden=false;$('#profileBadge').textContent=data.code||'Estudiante';overview=await(await request('/api/overview')).json();navigate('courses');}
function logout(){if(token)request('/api/logout',{method:'POST'}).catch(()=>{});token='';role='';active=null;feedback=null;sessionStorage.removeItem('adapta_v6_token');sessionStorage.removeItem('adapta_v6_role');window.adaptaIdleStop?.();showAuth()}
window.adaptaSessionInfo=()=>({token,role});
window.adaptaExpireIdleSession=(reason='Tu sesión ha caducado tras 15 minutos de inactividad. Inicia sesión de nuevo.')=>{
  token='';role='';active=null;feedback=null;stopTimer();
  try{if(novaAudio){novaAudio.pause();novaAudio=null};if('speechSynthesis' in window)speechSynthesis.cancel()}catch(e){}
  sessionStorage.removeItem('adapta_v6_token');sessionStorage.removeItem('adapta_v6_role');
  window.adaptaIdleStop?.();showAuth();
  const error=document.querySelector('#login-error');if(error)error.textContent=reason;
  const pass=document.querySelector('#accessPassword');if(pass)pass.value='';
  const teacherpass=document.querySelector('#accessTeacher');if(teacherpass)teacherpass.value='';
};
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function event(type,details={},task_id){if(token&&role==='student')request('/api/event',{method:'POST',body:{event_type:type,details,task_id:task_id||undefined}}).catch(()=>{})}
function closeMenu(){const bar=$('#sidebar');bar.classList.remove('open');$('#navScrim').hidden=true;$('#mobileMenu').setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}
function toggleMenu(){const opened=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',opened);$('#navScrim').hidden=!opened;$('#mobileMenu').setAttribute('aria-expanded',String(opened));document.body.classList.toggle('menu-open',opened)}
function navbind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#mobileMenu').onclick=toggleMenu;$('#navScrim').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});$('#logout').onclick=logout;$('#logoutTeacher').onclick=logout;$('#mentorToggle').onclick=()=>{const el=$('#mentorWidget');el.classList.toggle('open');event(el.classList.contains('open')?'mentor_open':'mentor_close',{page});};}
function say(text){const el=$('#mentorSpeech');el.textContent=text;if(window.innerWidth<=680 && page==='dashboard'){$('#mentorWidget').classList.remove('open');return;}$('#mentorWidget').classList.add('open');clearTimeout(mentorDismissTimer);mentorDismissTimer=setTimeout(()=>$('#mentorWidget').classList.remove('open'),7500)}
let novaAudio=null;
async function speak(text){
 const avatar=$('#mentorWidget');
 if(novaAudio){novaAudio.pause();novaAudio=null}
 if('speechSynthesis' in window)speechSynthesis.cancel();
 const lang=(document.documentElement.lang||'es').startsWith('en')?'en':'es';
 const finish=()=>{avatar?.classList.remove('speaking');avatar?.style.removeProperty('--mouth-open')};
 window.adaptaAmbientDuck?.();
 avatar?.classList.add('speaking');
 if(localStorage.getItem('adapta_neural_voice')==='yes'){
  try{
   const r=await fetch('/api/voice/neural',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({text:String(text).slice(0,1200),language:lang})});
   if(r.ok){
    const url=URL.createObjectURL(await r.blob());novaAudio=new Audio(url);
    novaAudio.onended=novaAudio.onerror=()=>{finish();URL.revokeObjectURL(url)};
    await novaAudio.play();return;
   }
  }catch(e){/* Fall back to browser speech */}
 }
 if(!('speechSynthesis' in window)){finish();toast('La síntesis de voz no está disponible');return}
 const u=new SpeechSynthesisUtterance(String(text).slice(0,2500));
 u.lang=lang==='es'?'es-ES':'en-GB';u.rate=.96;u.pitch=1;u.volume=.85;
 const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith(lang));
 u.voice=voices.find(v=>/natural|neural|premium|enhanced/i.test(v.name))||voices.find(v=>/google|microsoft/i.test(v.name))||voices[0]||null;
 u.onboundary=e=>{avatar?.style.setProperty('--mouth-open',e.charIndex%3===0?'8px':'3px')};
 u.onend=u.onerror=finish;speechSynthesis.speak(u);
}

function navigate(p){if(!['dashboard','diagnostic','practice','mentor','research','exams','courses','micro1','micro2'].includes(p))return;if(feedback){active=null}page=p;stopTimer();feedback=null;closeMenu();document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===p);if(b.dataset.page===p)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const names={dashboard:'Mi progreso',diagnostic:'Diagnóstico inicial',practice:'Práctica adaptativa',mentor:'Tutor personal',research:'Datos de investigación',exams:'Exámenes',courses:'Mis asignaturas',micro1:'Microeconomía I',micro2:'Microeconomía II'};$('#locationName').textContent=names[p];event('tab_view',{page:p});render();}
function meter(name,value){return `<div class="skill-row"><div class="skill-label"><span>${escapeHTML(name)}</span><strong>${Math.round(value*100)} %</strong></div><div class="track"><span style="width:${Math.round(value*100)}%"></span></div></div>`}
function section(head,content){return `<section class="card"><div class="card-head"><h2>${head}</h2></div>${content}</section>`}
function render(){if(page==='courses')return window.drawMicroCourses?.();if(page==='micro1'||page==='micro2')return window.drawMicroCourse?.(page);if(page==='dashboard')drawDashboard();if(page==='diagnostic')drawDiagnostic();if(page==='practice')drawPractice();if(page==='mentor')drawMentor();if(page==='research')drawResearch();if(page==='exams')drawExams()}
async function refreshOverview(){overview=await(await request('/api/overview')).json()}
function drawDashboard(){let o=overview,accuracy=o.graded?Math.round(o.correct*100/o.graded):0;let name=o.student.code;
$('#content').innerHTML=`<div class="eyebrow">APRENDER CON PROPÓSITO</div><section class="hero elevate"><div class="eyebrow">HOLA, ${escapeHTML(name)}</div><h1>El siguiente paso lo decides tú.</h1><p>Equivocarte es parte del aprendizaje. Practicaremos los conceptos que más te cuestan y avanzaremos cuando estés preparado.</p><div class="hero-actions"><button class="btn" id="heroStart">${o.diagnostic_complete?'Continuar practicando':'Empezar diagnóstico'} &nbsp;→</button><button class="btn hero-ghost" id="heroTutor">Consultar al tutor</button></div></section>
<div class="grid3"><div class="stat"><span>Respuestas registradas</span><b>${o.attempts}</b><small>Todos los tipos de pregunta</small><div class="stat-symbol">◫</div></div><div class="stat"><span>Respuestas verificadas</span><b>${accuracy}%</b><small>${o.correct} aciertos de ${o.graded} corregidas</small><div class="stat-symbol">✓</div></div><div class="stat"><span>Diagnóstico inicial</span><b>${o.diagnostic_count}/6</b><small>Competencias evaluadas</small><div class="stat-symbol">◉</div></div></div>
<div class="section-title"><h2>Tu mapa de competencias</h2><span class="pill neutral">Estimación BKT</span></div><div class="cols"><div class="card"><p class="muted-note">La barra representa una probabilidad estimada de dominio del concepto, no una calificación académica.</p>${o.topics.map(x=>meter(x,o.knowledge[x]??.24)).join('')}</div><div class="stack"><div class="guide"><div class="guide-icon">✦</div><div><strong>Tu ruta de aprendizaje</strong><p>${o.diagnostic_complete?'El sistema prioriza ejercicios según tus probabilidades de dominio, errores anteriores y práctica acumulada.':'Comienza con seis preguntas para identificar tu punto de partida en Microeconomía I.'}</p></div></div>${section('Tu curso',`<span class="topic-chip">${escapeHTML(o.student.degree)}</span><span class="topic-chip">Grupo ${escapeHTML(o.student.group_name)}</span><span class="topic-chip">${escapeHTML(o.student.professor)}</span><p class="muted-note">El sistema guarda tus respuestas, tiempos y pistas en el servidor de investigación.</p>`)}</div></div>`;
$('#heroStart').onclick=()=>navigate(o.diagnostic_complete?'practice':'diagnostic');$('#heroTutor').onclick=()=>navigate('mentor');say(o.diagnostic_complete?'Estoy analizando tus avances. Si algo no sale a la primera, revisaremos el razonamiento y lo intentaremos de otra forma.':'Empezaremos con un diagnóstico breve. No cuenta para una nota oficial: me ayudará a adaptar los siguientes problemas.');}
function drawDiagnostic(){let o=overview;if(o.diagnostic_complete){$('#content').innerHTML=`<section class="card elevate center" style="padding:45px"><div class="pill good">Diagnóstico completado</div><h1 style="margin-top:17px">Ya tenemos tu punto de partida.</h1><p class="muted">Has respondido una pregunta por competencia. Ahora empezarás a practicar a un nivel ajustado a tus resultados.</p><button class="btn btn-primary" id="diagDone">Comenzar práctica →</button></section>`;$('#diagDone').onclick=()=>navigate('practice');return}
$('#content').innerHTML=`<div class="eyebrow">PASO 1 · EVALUACIÓN INICIAL</div><h1>Descubramos qué sabes.</h1><p class="muted">Nueve preguntas, una por competencia. El diagnóstico no ofrece pistas ni se utiliza como examen oficial.</p><div id="questionHost"></div>`;
if(active?.phase==='diagnostico')return renderQuestion();$('#questionHost').innerHTML=`<div class="start-panel elevate"><h2>Diagnóstico: ${o.diagnostic_count} de 9</h2><p class="muted">El temporizador comienza cuando abras la siguiente pregunta. Tus resultados se registrarán automáticamente.</p><button id="startDiag" class="btn btn-primary">${o.diagnostic_count?'Siguiente pregunta':'Comenzar'} →</button></div>`;$('#startDiag').onclick=()=>startTask('diagnostico')}
function drawPractice(){if(!overview.diagnostic_complete){$('#content').innerHTML=`<section class="card"><h2>Primero, un diagnóstico breve</h2><p>Necesitamos una estimación inicial de tus nueve competencias antes de personalizar la dificultad.</p><button class="btn btn-primary" id="goDiag">Comenzar diagnóstico →</button></section>`;$('#goDiag').onclick=()=>navigate('diagnostic');return}
$('#content').innerHTML=`<div class="eyebrow">PASO 2 · APRENDIZAJE ADAPTATIVO</div><h1>Practica con sentido.</h1><p class="muted">Alternamos conceptos, análisis de gráficos científicos, pequeños cálculos y problemas de desarrollo. El sistema selecciona tu nivel utilizando el modelo bayesiano por competencia.</p><details class="filter-details" id="filterDetails" ${window.innerWidth>680?'open':''}><summary>Filtrar ejercicios <span class="muted-note">Competencia y modalidad</span></summary><div class="card filters"><div class="filter-item"><label for="topicSel">Competencia</label><select id="topicSel"><option value="">Todas (recomendado)</option>${TOPICS.map(t=>`<option ${topicFilter===t?'selected':''} value="${escapeHTML(t)}">${escapeHTML(t)}</option>`).join('')}</select></div><div class="filter-item"><label for="kindSel">Tipo de ejercicio</label><select id="kindSel"><option value="">Todos (recomendado)</option><option value="mcq" ${kindFilter==='mcq'?'selected':''}>Conceptos y casos (test)</option><option value="numeric" ${kindFilter==='numeric'?'selected':''}>Cálculo numérico</option><option value="development" ${kindFilter==='development'?'selected':''}>Problema de desarrollo</option><option value="graph" ${kindFilter==='graph'?'selected':''}>Interpretación de gráficos · Matplotlib</option></select></div><button class="btn btn-soft" id="resetFilters">Restablecer</button></div></details><div style="height:14px"></div><div id="questionHost"></div>`;
$('#topicSel').onchange=e=>{topicFilter=e.target.value;event('filter_changed',{topic:topicFilter,kind:kindFilter})};$('#kindSel').onchange=e=>{kindFilter=e.target.value;event('filter_changed',{topic:topicFilter,kind:kindFilter})};$('#resetFilters').onclick=()=>{topicFilter='';kindFilter='';drawPractice()};
if(active?.phase==='practica')return renderQuestion();$('#questionHost').innerHTML=`<div class="start-panel elevate"><span class="pill">Tutoría adaptativa</span><h2 style="margin-top:12px">Un ejercicio, un objetivo</h2><p class="muted">Tendrás tiempo para pensar y una pista opcional. Tu tutor explicará los conceptos cuando respondas.</p><button class="btn btn-primary" id="startPractice">Preparar siguiente ejercicio →</button></div>`;$('#startPractice').onclick=()=>startTask('practica')}
async function startTask(phase){if(active)return renderQuestion();try{const payload={phase,topic:phase==='diagnostico'?null:(topicFilter||null),kind:phase==='diagnostico'?null:(kindFilter||null)};const data=await(await request('/api/task',{method:'POST',body:payload})).json();if(data.complete){await refreshOverview();active=null;drawDiagnostic();return}active={...data,phase};feedback=null;timerWarningSent=false;renderQuestion();say('Tómate tu tiempo. Lee qué te piden, identifica los datos y elige el procedimiento adecuado.')}catch(e){toast(e.message)}}
function remaining(){if(!active)return 0;return Math.max(0,(Date.parse(active.deadline)-Date.now())/1000)}
function fmtTime(seconds){let n=Math.ceil(Math.max(0,seconds));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function drawTimer(){
 if(!active)return;
 const value=$('#timerValue'),ring=$('#timerRing'),bar=$('#timeBar'),status=$('#timeStatus');
 if(!value||!ring)return;
 const seconds=remaining(),ratio=Math.min(1,Math.max(0,seconds/active.time_limit));
 value.textContent=fmtTime(seconds);
 ring.style.setProperty('--timer-deg',Math.round(ratio*360)+'deg');
 ring.classList.toggle('urgent',seconds<25);ring.style.setProperty('--timer-color',`hsl(${Math.round(120*ratio)} 78% 39%)`);ring.style.setProperty('--timer-ratio',ratio);
 if(bar){bar.style.width=Math.round(ratio*100)+'%';bar.classList.toggle('urgent',seconds<25);bar.style.background=`linear-gradient(90deg,#cb0017,hsl(${Math.round(120*ratio)} 78% 39%))`}
 if(status)status.textContent=seconds<25?'Últimos segundos: revisa tu respuesta':seconds<active.time_limit*.4?'Avanza con calma y comprueba el resultado':'Tiempo disponible';
 if(seconds<30&&seconds>0&&!timerWarningSent){timerWarningSent=true;event('timer_warning',{seconds_remaining:Math.round(seconds),question_id:active.question.id},active.task_id)}
 if(seconds<=0&&!submitting&&!feedback)submitAnswer(true)
}
function renderQuestion(){
 stopTimer();if(!active)return;
 const q=active.question,kind=q.kind,isDiag=active.phase==='diagnostico';
 const kindName=kind==='graph'?'Interpretación gráfica · Matplotlib':kind==='mcq'?'Conceptual y aplicado':kind==='numeric'?'Cálculo verificado':'Desarrollo argumentativo';
 const isChoice=kind==='mcq'||kind==='graph';
 const form=isChoice?`<div class="options ${kind==='graph'?'chart-options':''}" role="radiogroup" aria-label="Opciones de respuesta">${q.options.map((op,i)=>`<label class="option glass-option"><input type="radio" name="answer" value="${i}"><span class="option-key" aria-hidden="true">${String.fromCharCode(65+i)}</span><span class="option-copy">${escapeHTML(op)}</span><span class="option-check" aria-hidden="true">✓</span></label>`).join('')}</div>`:
   kind==='numeric'?`<label for="answerNum" class="label">Tu resultado ${escapeHTML(q.unit||'')}</label><input id="answerNum" type="text" inputmode="decimal" class="input" autocomplete="off" placeholder="Introduce un número; puedes usar coma decimal">`:
   `<label for="answerLong" class="label">Explica tu razonamiento</label><textarea id="answerLong" rows="8" maxlength="5000" placeholder="Organiza la respuesta: planteamiento, desarrollo, conclusión y supuestos..."></textarea><p class="muted-note">Este problema queda pendiente de valoración docente y no se califica automáticamente.</p>`;
 const graphic=kind==='graph'?`<figure class="graph-figure"><div class="graph-top"><span class="plot-badge">▧ GRÁFICO ECONÓMICO</span><button type="button" id="expandGraph" class="btn btn-outline btn-sm" aria-label="Ampliar gráfico">⛶ Ampliar</button></div><img id="economicGraph" class="plot-image" src="${escapeHTML(q.graph)}" alt="${escapeHTML(q.graph_alt)}" width="970" height="620"><figcaption>${escapeHTML(q.graph_caption)}</figcaption></figure>`:'';
 const modal=kind==='graph'?`<dialog class="plot-dialog" id="plotModal" aria-label="Gráfico ampliado"><div class="modal-head"><strong>Analiza el gráfico</strong><button type="button" class="btn btn-soft" id="closePlot">Cerrar ✕</button></div><img src="${escapeHTML(q.graph)}" alt="${escapeHTML(q.graph_alt)}"><p class="muted-note">${escapeHTML(q.graph_caption)}</p></dialog>`:'';
 $('#questionHost').innerHTML=`<div class="card elevate question question-v8"><div class="question-header"><div class="question-meta"><span class="pill">${escapeHTML(q.topic)}</span><span class="pill neutral">Nivel ${q.level}/3 · ${kindName}</span><p class="muted-note" style="margin:10px 0 0">${isDiag?'Diagnóstico inicial':'Práctica personalizada'} · Ejercicio #${q.id}</p></div><div class="glass-timer" role="timer" aria-label="Tiempo restante"><span class="timer" id="timerRing"><b id="timerValue">${fmtTime(remaining())}</b></span><div class="timer-copy"><b>TIEMPO RESTANTE</b><span id="timeStatus" aria-live="polite">Tiempo disponible</span><div class="time-track" aria-hidden="true"><div id="timeBar"></div></div></div></div></div><div class="question-intro"><span class="question-step">OBSERVA · RAZONA · RESPONDE</span><h2>${escapeHTML(q.prompt)}</h2>${q.reference?`<p class="muted-note">Caso aplicado · <a href="${escapeHTML(q.reference)}" target="_blank" rel="noopener noreferrer">Fuente de referencia</a></p>`:''}</div><div class="exercise-layout ${kind==='graph'?'has-chart':''}">${graphic}<div class="exercise-input"><form id="answerForm">${kind==='graph'?'<p class="option-instructions">Selecciona la interpretación correcta de la figura:</p>':''}${form}<div class="answer-actions"><button type="submit" class="btn btn-primary" id="submitBtn">Comprobar respuesta <span aria-hidden="true">→</span></button>${isDiag?'':`<button type="button" class="btn btn-outline" id="hintBtn">✧ Necesito una pista</button>`}</div></form></div></div><div id="hintBox"></div><div id="feedbackBox"></div></div>${modal}`;
 $('#answerForm').onsubmit=e=>{e.preventDefault();submitAnswer(false)};
 if(!isDiag)$('#hintBtn').onclick=async()=>{try{const res=await(await request(`/api/task/${encodeURIComponent(active.task_id)}/hint`,{method:'POST'})).json();active.hints=res.count;$('#hintBox').innerHTML=`<div class="guide" style="margin-top:19px"><div class="guide-icon">?</div><div><strong>Una pista para seguir</strong><p>${escapeHTML(res.hint)}</p></div></div>`;say(res.hint)}catch(e){toast(e.message)}};
 if(kind==='graph'){
   const img=$('#economicGraph');
   let viewed=false;const markViewed=()=>{if(viewed)return;viewed=true;event('graph_viewed',{question_id:q.id},active?.task_id)};img.addEventListener('load',markViewed,{once:true});if(img.complete&&img.naturalWidth)markViewed();
   $('#expandGraph').onclick=()=>{const dlg=$('#plotModal');if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','');event('graph_zoomed',{question_id:q.id},active.task_id)};
   $('#closePlot').onclick=()=>{const dlg=$('#plotModal');if(typeof dlg.close==='function')dlg.close();else dlg.removeAttribute('open')};
   $('#plotModal').onclick=e=>{if(e.target.id==='plotModal')e.target.close()};
 }
 if(isChoice){let selectionCount=0;$('#answerForm').querySelectorAll('input[name="answer"]').forEach(r=>r.addEventListener('change',()=>{selectionCount++;event('option_selected',{question_id:q.id,option:r.value,count:selectionCount},active.task_id)}))}
 else{
   $('#answerForm').addEventListener('input',()=>{clearTimeout(answerEditTimer);answerEditTimer=setTimeout(()=>{
      const length=kind==='numeric'?$('#answerNum')?.value?.length:$('#answerLong')?.value?.length;
      event('answer_edited',{question_id:q.id,note:'longitud='+Math.min(length||0,5000)},active?.task_id)
   },2200)})
 }
 restoreDraft();$('#answerForm').addEventListener('input',saveDraft);$('#answerForm').addEventListener('change',saveDraft);
 drawTimer();timerHandle=setInterval(drawTimer,250)
}
function draftKey(){return active ? 'adapta_task_draft_v8_'+active.task_id : null}
function saveDraft(){const key=draftKey();if(!key||!$('#answerForm'))return;const q=active.question;let val=null;
 if(q.kind==='mcq'||q.kind==='graph')val=$('input[name="answer"]:checked')?.value??null;
 else if(q.kind==='numeric')val=$('#answerNum')?.value??'';
 else val=$('#answerLong')?.value??'';
 try{sessionStorage.setItem(key,JSON.stringify({value:val,kind:q.kind,updated:Date.now()}))}catch{}}
function restoreDraft(){const key=draftKey();if(!key)return;let saved;try{saved=JSON.parse(sessionStorage.getItem(key))}catch{return}
 if(!saved||saved.kind!==active.question.kind)return;
 if((saved.kind==='mcq'||saved.kind==='graph')&&saved.value!==null){const input=document.querySelector('input[name="answer"][value="'+String(saved.value).replace(/[^0-9]/g,'')+'"]');if(input)input.checked=true;}
 if(saved.kind==='numeric'&&$('#answerNum'))$('#answerNum').value=saved.value;
 if(saved.kind==='development'&&$('#answerLong'))$('#answerLong').value=saved.value;
}

async function submitAnswer(expired){if(submitting||!active||feedback)return;let q=active.question;let answer=null;
if(!expired){if(q.kind==='mcq'||q.kind==='graph'){const radio=$('input[name="answer"]:checked');if(!radio){toast('Selecciona una respuesta antes de enviarla.');return}answer=Number(radio.value)}else if(q.kind==='numeric'){answer=$('#answerNum').value.trim();if(!answer){toast('Introduce tu resultado numérico.');return}if(!/^[+-]?\d+(?:[.,]\d+)?$/.test(answer)){toast('Introduce un número válido.');return}}else{answer=$('#answerLong').value.trim();if(answer.length<20){toast('Desarrolla un poco más tu razonamiento (mínimo 20 caracteres).');return}}}
submitting=true;stopTimer();$('#submitBtn').disabled=true;
try{const seconds=Math.max(0,(Date.now()-Date.parse(active.started))/1000);feedback=await(await request('/api/answer',{method:'POST',body:{task_id:active.task_id,answer,client_seconds:Math.round(seconds*100)/100,timed_out:expired}})).json();
if(expired)event('timer_expired',{page},active.task_id);try{sessionStorage.removeItem(draftKey())}catch{}renderFeedback();await refreshOverview();}
catch(e){toast(e.message);$('#submitBtn').disabled=false;if(active)timerHandle=setInterval(drawTimer,250)}finally{submitting=false}}
function renderFeedback(){clearTimeout(answerEditTimer);if(!feedback||!active)return;const f=feedback,q=active.question;const expired=f.timed_out;const pending=f.correct===null;const title=expired?'Se ha agotado el tiempo':pending?'Respuesta recibida para revisión':f.correct?'¡Bien razonado!':'Una oportunidad para aprender';let cls=expired?'bad':pending?'pending':f.correct?'':'bad';let advice=expired?'No pasa nada: el tiempo es una referencia para organizar tu trabajo. Vamos a revisar el procedimiento.':pending?'Gracias por desarrollar tu respuesta. Tu profesor podrá valorarla con la rúbrica; aquí tienes una propuesta de solución para contrastarla.':f.correct?'Has aplicado correctamente el concepto. Observa el procedimiento para consolidarlo.':'El error puede ayudarnos a detectar qué concepto conviene repasar. Te explico el procedimiento paso a paso.';
$('#answerForm').style.display='none';$('#hintBox').style.display='none';$('#feedbackBox').innerHTML=`<div class="feedback ${cls}"><h3>${title}</h3><p>${advice}</p><div class="pedagogic-explanation"><h4>Comprendamos la solución</h4><p>${escapeHTML(f.explanation)}</p><p><strong>Para recordar:</strong> ${escapeHTML(lessons[q.topic]?.idea||'Identifica los supuestos, interpreta el resultado y contrasta sus unidades.')}</p><p><strong>Comprueba tu razonamiento:</strong> ${escapeHTML(lessons[q.topic]?.steps?.[0]||'Explica por qué la solución es coherente con la teoría.')}</p></div>${!pending?`<p><strong>Solución:</strong> ${escapeHTML(f.answer)}</p>`:`<p><strong>Estado:</strong> pendiente de calificación docente.</p><p>${escapeHTML(f.rubric||'')}</p>`}${f.p_after!==null&&f.p_after!==undefined?`<p class="muted-note">Dominio estimado del tema: ${Math.round(f.p_before*100)} % → <strong>${Math.round(f.p_after*100)} %</strong> (modelo bayesiano no calibrado).</p>`:''}<div class="answer-actions"><button id="next" class="btn btn-primary">${active.phase==='diagnostico'?'Continuar diagnóstico':'Siguiente ejercicio'} →</button><button id="voiceExplanation" class="btn btn-soft">♫ Escuchar explicación</button><button id="learnMore" class="btn btn-outline">Repasar concepto</button></div></div>`;
$('#next').onclick=async()=>{const prevphase=active.phase;active=null;feedback=null;if(prevphase==='diagnostico'&&overview.diagnostic_complete){navigate('dashboard');toast('¡Diagnóstico completado!');}else{if(prevphase==='diagnostico'){drawDiagnostic();await startTask('diagnostico')}else{drawPractice();await startTask('practica')}}};
$('#voiceExplanation').onclick=()=>speak(f.explanation);
$('#learnMore').onclick=()=>{tutorTopic=q.topic;active=null;feedback=null;navigate('mentor')};
say(f.correct?'¡Buen trabajo! '+f.explanation:advice+' '+f.explanation);event('feedback_read',{topic:q.topic},active.task_id)}
function drawMentor(){const t=lessons[tutorTopic];$('#content').innerHTML=`<div class="eyebrow">TUTORÍA PEDAGÓGICA</div><h1>Aprender también es preguntar.</h1><p class="muted">NOVA te acompaña con explicaciones contrastables, ejemplos y pasos pequeños. Sus respuestas proceden de contenido docente estructurado, no de generación libre de IA.</p><section class="card"><h2>¿Qué tema quieres comprender mejor?</h2><div class="tutor-topics">${TOPICS.map(x=>`<button data-tutor="${escapeHTML(x)}" class="${tutorTopic===x?'selected':''}">${escapeHTML(x)}</button>`).join('')}</div></section><section class="tutor-box"><div class="between"><h2>Hablemos de ${escapeHTML(tutorTopic).toLowerCase()}</h2><div class="tutor-visual" aria-hidden="true">✦</div></div><div class="message"><div class="message-avatar">N</div><div class="bubble">${escapeHTML(t.idea)}</div></div><h3>Lo resolvemos en tres pasos</h3><ol>${t.steps.map(step=>`<li style="margin:12px 0;line-height:1.5">${escapeHTML(step)}</li>`).join('')}</ol><div class="guide"><div class="guide-icon">!</div><div><strong>Un error frecuente</strong><p>${escapeHTML(t.error)}</p></div></div><div class="message"><div class="message-avatar">N</div><div class="bubble"><strong>Ejemplo resuelto:</strong> ${escapeHTML(t.example)}</div></div><div class="answer-actions"><button class="btn btn-primary" id="tutorPractice">Practicar este tema →</button><button class="btn btn-soft" id="tutorSpeak">♫ Escuchar</button><label class="neural-choice"><input type="checkbox" id="neuralVoiceChoice"> Voz neuronal (requiere servicio configurado)</label></div></section>`;
document.querySelectorAll('[data-tutor]').forEach(b=>b.onclick=()=>{tutorTopic=b.dataset.tutor;drawMentor()});$('#tutorPractice').onclick=()=>{topicFilter=tutorTopic;kindFilter='';navigate('practice')};$('#tutorSpeak').onclick=()=>speak(t.idea+' '+t.steps.join('. '));const voiceChoice=$('#neuralVoiceChoice');if(voiceChoice){voiceChoice.checked=localStorage.getItem('adapta_neural_voice')==='yes';voiceChoice.onchange=()=>localStorage.setItem('adapta_neural_voice',voiceChoice.checked?'yes':'no')}say('Los errores no te definen. Lo importante es entender por qué ocurre cada resultado.')}
function drawResearch(){$('#content').innerHTML=`<div class="eyebrow">TRANSPARENCIA Y METODOLOGÍA</div><h1>Tu actividad, con trazabilidad.</h1><p class="muted">El estudio analiza aprendizaje, no la identidad personal. Tu código está separado de tu nombre y el profesor conserva un registro centralizado de tus respuestas.</p>${section('¿Qué se registra?',`<div class="grid3"><div class="guide"><div class="guide-icon">1</div><div><strong>Respuestas</strong><p>Pregunta, tema, modalidad, figura analizada, nivel, respuesta y resultado.</p></div></div><div class="guide"><div class="guide-icon">2</div><div><strong>Tiempo</strong><p>Inicio y fin de ejercicio, duración y tiempo agotado.</p></div></div><div class="guide"><div class="guide-icon">3</div><div><strong>Aprendizaje</strong><p>Pistas, selección y cambio de opciones, ampliación de gráficos, avisos del reloj y probabilidad de dominio estimada antes y después.</p></div></div></div>`)}<div class="research-notice"><strong>Sobre el modelo adaptativo.</strong> Se utiliza Bayesian Knowledge Tracing (BKT) por competencia con parámetros iniciales no calibrados en una muestra real. El algoritmo orienta la práctica, pero sus probabilidades no sustituyen notas oficiales ni constituyen resultados científicos validados. La asignación a grupos y los consentimientos deben gestionarse bajo un protocolo ético autorizado.</div>`;}
let prepared=[];
async function renderTeacher(){const data=await(await request('/api/teacher/overview')).json();const s=data.students||[];let activeN=s.filter(x=>x.active).length,total=s.reduce((a,x)=>a+x.answers,0),graded=s.reduce((a,x)=>a+x.graded,0),correct=s.reduce((a,x)=>a+x.correct,0),graphs=s.reduce((a,x)=>a+(x.graph_attempts||0),0),graphCorrect=s.reduce((a,x)=>a+(x.graph_correct||0),0);
$('#teacherContent').innerHTML=`<div class="eyebrow">PANEL DE INVESTIGACIÓN</div><div class="between" style="align-items:flex-start;flex-wrap:wrap"><div><h1>Una visión conjunta del aprendizaje.</h1><p class="muted">Cohorte de Microeconomía I · Datos sincronizados y respuestas verificadas por el servidor.</p></div><button class="btn btn-primary" id="downloadExcel">▣ Excel completo: Micro I y II</button></div><div class="grid3"><div class="stat"><span>Participantes</span><b>${s.length}</b><small>${activeN} cuentas activadas</small></div><div class="stat"><span>Respuestas registradas</span><b>${total}</b><small>${data.bank_count} ejercicios disponibles</small></div><div class="stat"><span>Tasa de acierto</span><b>${graded?Math.round(100*correct/graded):0}%</b><small>${correct}/${graded} respuestas calificables</small></div></div>
<div class="graph-insight"><div class="graph-insight-icon">▧</div><div><b>Interpretación gráfica</b><p>${data.graph_count} gráficos originales con Matplotlib · ${graphs} respuestas · ${graphs?Math.round(100*graphCorrect/graphs):0} % de aciertos</p></div><span class="pill neutral">Registro individual por alumno</span></div><div class="section-title"><h2>Incorporación de estudiantes</h2><span class="pill neutral">Asignación desde docencia</span></div><div class="card"><p class="muted-note">Genera identificadores e invitaciones, con grupos equilibrados A–D o un grupo prefijado. El estudiante no puede autoasignarse su tratamiento. Descarga las invitaciones en CSV al generarlas: no podrán recuperarse después.</p><div class="filters"><div class="filter-item"><label for="teacherDegree">Titulación</label><select id="teacherDegree"><option>ADE</option><option>Economía</option><option>Finanzas y Contabilidad</option><option>Doble Grado ADE-Derecho</option></select></div><div class="filter-item"><label for="teacherProfessor">Profesor responsable</label><input class="input" id="teacherProfessor" placeholder="Identificación del docente" value="Docente Microeconomía I"></div><div class="filter-item"><label for="teacherN">N.º de alumnos</label><input id="teacherN" class="input" type="number" min="1" max="120" value="12"></div></div><div class="answer-actions"><label class="label" for="teacherGroup">Grupo / asignación</label><select style="max-width:220px" id="teacherGroup"><option value="balanced">Equilibrada A/B/C/D</option><option>A</option><option>B</option><option>C</option><option>D</option></select><button class="btn btn-soft" id="createStudents">Crear invitaciones</button><button class="btn btn-outline" id="inviteCsv" ${enrollmentList.length?'':'disabled'}>Exportar invitaciones CSV</button></div><div id="enrollmentResult"></div></div>
<div class="section-title"><h2>Seguimiento por estudiante</h2><button class="btn btn-outline btn-sm" id="refreshTeacher">↻ Actualizar</button></div><div class="card table-overflow"><table class="summary-table"><thead><tr><th>Código</th><th>Grupo</th><th>Titulación</th><th>Profesor</th><th>Activación</th><th>Respuestas</th><th>Aciertos</th><th>Tiempo medio</th><th>Gráficos (aciertos/intentos)</th></tr></thead><tbody>${s.map(x=>`<tr><td><b>${escapeHTML(x.code)}</b></td><td><span class="pill neutral">${escapeHTML(x.group_name)}</span></td><td>${escapeHTML(x.degree)}</td><td>${escapeHTML(x.professor)}</td><td>${x.active?'Sí':'Pendiente'}</td><td>${x.answers}</td><td>${x.graded?Math.round(x.correct*100/x.graded)+' %':'—'}</td><td>${x.avg_seconds??'—'} s</td><td>${x.graph_correct||0} / ${x.graph_attempts||0}</td></tr>`).join('')}</tbody></table></div><div class="research-notice"><strong>Uso de investigación:</strong> las asignaciones equilibradas no sustituyen la aleatorización preregistrada, el consentimiento ni los controles contra la contaminación. Esta instalación no está certificada para despliegue institucional; exige HTTPS, medidas antiabuso, revisión RGPD y separación de permisos por investigador.</div>`;
$('#teacherContent').insertAdjacentHTML('afterbegin',`<div class="card" style="margin-bottom:20px"><h2>Exámenes inteligentes</h2><p>Publica exámenes para alumnos y registra noticias económicas revisadas con su fuente primaria.</p><button class="btn btn-primary" id="teacherExams">Configurar exámenes</button></div>`);$('#teacherExams').onclick=()=>drawExams(true);$('#downloadExcel').onclick=downloadExcel;$('#refreshTeacher').onclick=renderTeacher;$('#inviteCsv').onclick=downloadInvites;$('#createStudents').onclick=createStudents;if(enrollmentList.length)showInvitations();}
async function createStudents(){const b=$('#createStudents');b.disabled=true;try{const qty=Number($('#teacherN').value);const g=$('#teacherGroup').value;const data=await(await request('/api/teacher/enroll',{method:'POST',body:{quantity:qty,degree:$('#teacherDegree').value,professor:$('#teacherProfessor').value,assignment:g==='balanced'?'balanced':'fixed',fixed_group:g==='balanced'?null:g}})).json();enrollmentList=data.enrollments;showInvitations();toast('Invitaciones creadas. Descarga el CSV ahora.');$('#inviteCsv').disabled=false;}catch(e){toast(e.message)}finally{b.disabled=false}}
function showInvitations(){const host=$('#enrollmentResult');if(!host||!enrollmentList.length)return;host.innerHTML=`<div class="guide" style="margin-top:18px"><div class="guide-icon">!</div><div><strong>Guarda las invitaciones antes de salir</strong><p>Se muestran una sola vez; distribúyelas individualmente. ${enrollmentList.length} códigos creados.</p></div></div><div class="table-overflow"><table class="summary-table"><thead><tr><th>Alumno</th><th>Grupo</th><th>Invitación individual</th></tr></thead><tbody>${enrollmentList.map(x=>`<tr><td>${escapeHTML(x.code)}</td><td>${escapeHTML(x.group)}</td><td><code>${escapeHTML(x.invite)}</code></td></tr>`).join('')}</tbody></table></div>`}
function downloadFile(blob,filename){const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),2000)}
async function downloadExcel(){try{const response=await request('/api/micro/teacher/export.xlsx');downloadFile(await response.blob(),'MICRO_ADAPTA_ITS_Investigacion_Completa.xlsx')}catch(e){toast(e.message)}}
function downloadInvites(){if(!enrollmentList.length)return;const header=['Codigo','Grupo','Invitacion','Titulacion','Profesor'];let csv='\ufeff'+header.join(';')+'\r\n'+enrollmentList.map(o=>[o.code,o.group,o.invite,o.degree,o.professor].map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\r\n');downloadFile(new Blob([csv],{type:'text/csv;charset=utf-8'}),'ADAPTA_ITS_invitaciones_privadas.csv')}
window.addEventListener('visibilitychange',()=>{if(role==='student')event(document.hidden?'page_hidden':'page_visible',{page},active?.task_id)});
