let examRun=null,examInterval=null,examAnswers={},examIndex=0;
function examForm(teacher=false){
 return `<div class="card elevate exam-config"><h2>${teacher?'Crear examen docente':'Crear autoevaluación'}</h2><label class="label">Título</label><input class="input" id="examTitle" value="${teacher?'Evaluación de Microeconomía I':'Mi autoevaluación'}" maxlength="120"><p class="label">Selecciona los temas</p><div class="exam-topic-grid">${TOPICS.map(t=>`<label><input type="checkbox" class="exam-topic" value="${escapeHTML(t)}" checked> ${escapeHTML(t)}</label>`).join('')}</div><p class="label">Modalidades</p><div class="exam-topic-grid">${[['mcq','Teoría y test'],['graph','Interpretación gráfica'],['numeric','Problemas numéricos'],['news','Noticias económicas documentadas']].map(([k,v])=>`<label><input class="exam-kind" type="checkbox" value="${k}" ${k==='news'?'':'checked'}> ${v}</label>`).join('')}</div><div class="exam-fields"><label>Preguntas<input id="examCount" type="number" min="1" max="${teacher?100:50}" value="10"></label><label>Duración (minutos)<input id="examDuration" type="number" min="5" max="180" value="30"></label></div><label class="exam-check"><input id="examAdaptive" type="checkbox" checked> Ajustar la dificultad al dominio previo del estudiante</label>${teacher?'<label class="exam-check"><input id="examPublished" type="checkbox" checked> Publicar para los estudiantes</label>':''}<p class="muted-note">La selección adaptativa se fija al comenzar el examen. Durante la prueba no se cambian las preguntas. Las noticias solo están disponibles si el profesor ha incorporado y revisado su fuente.</p><button class="btn btn-primary" id="saveExam">Guardar examen</button><p id="examError" class="error-text"></p></div>`;
}
async function drawExams(teacher=false){
 clearInterval(examInterval);examInterval=null;
 const host=teacher?$('#teacherContent'):$('#content');if(!host)return;
 host.innerHTML=`<div class="eyebrow">EVALUACIÓN INTELIGENTE</div><h1>${teacher?'Exámenes del profesorado':'Exámenes y autoevaluación'}</h1><div id="examList" class="card" style="margin-bottom:20px">Cargando...</div>${examForm(teacher)}${teacher?'<div class="card" style="margin-top:20px"><h2>Incorporar noticia económica</h2><p class="muted-note">Introduzca únicamente noticias cuya fuente primaria haya comprobado. El sistema no verifica automáticamente los hechos.</p><form id="newsForm" class="stack"><select id="newsTopic">'+TOPICS.map(t=>`<option>${escapeHTML(t)}</option>`).join('')+'</select><input id="newsTitle" class="input" placeholder="Título de la noticia" required><input id="newsSource" class="input" placeholder="Fuente (por ejemplo, Eurostat)" required><input id="newsDate" class="input" type="date" required><input id="newsUrl" class="input" type="url" placeholder="https://..." required><textarea id="newsPrompt" placeholder="Pregunta de interpretación" required></textarea><textarea id="newsOptions" placeholder="Opciones, una por línea (2-6)" required></textarea><label>Índice de la respuesta correcta (1-6)<input id="newsCorrect" type="number" min="1" max="6" value="1"></label><textarea id="newsExplanation" placeholder="Explicación económica y justificación" required></textarea><button class="btn btn-soft" type="submit">Registrar noticia revisada</button></form></div>':''}`;
 if(teacher){
 const form=document.createElement('section');form.className='card elevate';form.style.marginTop='20px';
 form.innerHTML='<h2>Importar banco de preguntas</h2><p class="muted-note">Admite Excel, Word, PDF, CSV e imágenes escaneadas (PNG/JPG/WebP). El OCR interpreta texto, pero las fórmulas y respuestas requieren revisión docente. Las preguntas quedan pendientes de revisión y no se publican automáticamente.</p><p class="muted-note">Columnas: topic, kind (mcq/numeric), level (1-3), prompt, options (separadas por |), answer (índice desde 0 para test), explanation, hint, unit, reference. En Word/PDF utiliza «campo: valor» y separa preguntas con ---.</p><input type="file" id="questionImportFile" accept=".xlsx,.docx,.pdf,.csv,.png,.jpg,.jpeg,.webp"><button class="btn btn-primary" id="uploadQuestionBank" type="button">Analizar e importar</button><div id="questionImportResult" role="status"></div><button class="btn btn-outline" id="reviewQuestionBank" type="button">Revisar preguntas pendientes</button><div id="questionReviewList"></div>';
 host.appendChild(form);
 $('#uploadQuestionBank').onclick=async()=>{const file=$('#questionImportFile').files[0];if(!file){toast('Selecciona un archivo');return}if(file.size>8*1024*1024){toast('Máximo 8 MB');return}const fd=new FormData();fd.append('file',file);try{const r=await fetch('/api/teacher/import/questions',{method:'POST',headers:{Authorization:'Bearer '+token},body:fd});const data=await r.json();if(!r.ok)throw Error(data.detail||'No se pudo importar');$('#questionImportResult').textContent=data.staged+' preguntas pendientes; '+data.errors.length+' filas rechazadas. '+data.errors.slice(0,5).map(e=>'Fila '+e.row+': '+e.error).join('; ')}catch(e){toast(e.message)}};
 $('#reviewQuestionBank').onclick=async()=>{try{const data=await(await request('/api/teacher/import/questions')).json();const box=$('#questionReviewList');box.innerHTML='<p>'+data.questions.length+' preguntas pendientes</p>'+data.questions.map(q=>'<label class="exam-check"><input type="checkbox" class="approve-import" value="'+q.id+'"><span><b>'+escapeHTML(q.topic)+'</b> · '+escapeHTML(q.prompt)+'<br><small>Respuesta: '+escapeHTML(q.answer)+' · '+escapeHTML(q.explanation)+'</small></span></label>').join('')+'<button class="btn btn-primary" id="approveSelectedImports">Aprobar seleccionadas</button>';$('#approveSelectedImports').onclick=async()=>{const ids=[...box.querySelectorAll('.approve-import:checked')].map(x=>Number(x.value));if(!ids.length)return toast('Selecciona preguntas');await request('/api/teacher/import/approve',{method:'POST',body:{ids}});toast('Preguntas aprobadas: '+ids.length);$('#reviewQuestionBank').click()}}catch(e){toast(e.message)}};
}
$('#saveExam').onclick=async()=>{
 try{const topics=[...host.querySelectorAll('.exam-topic:checked')].map(x=>x.value),kinds=[...host.querySelectorAll('.exam-kind:checked')].map(x=>x.value);
 const payload={title:$('#examTitle').value,topics,kinds,question_count:Number($('#examCount').value),duration_minutes:Number($('#examDuration').value),adaptive:$('#examAdaptive').checked,published:teacher?$('#examPublished').checked:false};
 await request('/api/exams',{method:'POST',body:payload});toast('Examen creado');drawExams(teacher);
 }catch(e){$('#examError').textContent=e.message}};
 if(teacher)$('#newsForm').onsubmit=async e=>{e.preventDefault();try{
 const options=$('#newsOptions').value.split('\n').map(x=>x.trim()).filter(Boolean);
 await request('/api/exams/news',{method:'POST',body:{topic:$('#newsTopic').value,title:$('#newsTitle').value,source:$('#newsSource').value,published_date:$('#newsDate').value,url:$('#newsUrl').value,prompt:$('#newsPrompt').value,options,correct_index:Number($('#newsCorrect').value)-1,explanation:$('#newsExplanation').value}});toast('Noticia registrada por el docente');drawExams(true)
 }catch(err){toast(err.message)}};
 try{const data=await(await request('/api/exams')).json();$('#examList').innerHTML='<h2>Exámenes disponibles</h2>'+(data.exams.length?data.exams.map(x=>`<div class="exam-list-row"><div><strong>${escapeHTML(x.title)}</strong><p class="muted-note">${x.question_count} preguntas · ${x.duration_minutes} min · ${x.adaptive?'Dificultad adaptativa':'Dificultad común'} · ${x.published?'Publicado':'Privado'}</p></div>${teacher?'':`<button class="btn btn-soft" data-exam="${escapeHTML(x.id)}">Comenzar o continuar</button>`}</div>`).join(''):'<p>Aún no hay exámenes creados.</p>');
 host.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>startExam(b.dataset.exam));
 }catch(e){$('#examList').textContent=e.message}
}
async function startExam(id){try{examRun=await(await request('/api/exams/'+encodeURIComponent(id)+'/start',{method:'POST'})).json();examAnswers=examRun.answers||{};examIndex=0;if(examRun.finished){const result=await(await request('/api/exams/runs/'+encodeURIComponent(examRun.run_id)+'/finish',{method:'POST'})).json();$('#content').innerHTML='<section class="card"><h2>Examen ya entregado</h2><p>Calificación: '+result.score+'/10 · '+result.correct+'/'+result.total+' respuestas correctas.</p><button class="btn btn-primary" id="backExams">Volver</button></section>';$('#backExams').onclick=()=>drawExams(false)}else drawExamQuestion()}catch(e){toast(e.message)}}
function drawExamQuestion(){
 if(!examRun)return;
 const host=$('#content'),q=examRun.questions[examIndex],saved=examAnswers[String(q.id)];
 const remaining=Math.max(0,Math.ceil((Date.parse(examRun.deadline)-Date.now())/1000));
 host.innerHTML=`<section class="card elevate"><div class="between"><div><span class="pill">Examen</span><h2>${escapeHTML(examRun.title)}</h2><p class="muted-note">Pregunta ${examIndex+1} de ${examRun.questions.length} · ${escapeHTML(q.topic)}</p></div><div class="glass-timer"><span class="timer" id="timerRing"><b id="timerValue">${fmtTime(remaining)}</b></span></div></div><div class="question-intro"><h2>${escapeHTML(q.prompt)}</h2></div>${q.graph?'<img class="plot-image" src="'+escapeHTML(q.graph)+'" alt="'+escapeHTML(q.graph_alt||'Gráfico')+'">':''}${q.reference?'<p class="muted-note">Fuente: <a target="_blank" rel="noopener noreferrer" href="'+escapeHTML(q.reference)+'">'+escapeHTML(q.news_source||'Documento de referencia')+'</a> '+escapeHTML(q.news_date||'')+'</p>':''}<div id="examOptions">${q.kind==='numeric'?'<input class="input" id="examValue" inputmode="decimal" placeholder="Introduce tu respuesta" value="'+escapeHTML(saved??'')+'">':q.options.map((o,i)=>'<label class="option"><input type="radio" name="examChoice" value="'+i+'" '+(String(saved)===String(i)?'checked':'')+'> '+escapeHTML(o)+'</label>').join('')}</div><p id="examSaveStatus" class="muted-note">Las respuestas se guardan en el servidor.</p><div class="answer-actions"><button class="btn btn-outline" id="examPrev" ${examIndex===0?'disabled':''}>Anterior</button><button class="btn btn-soft" id="examNext" ${examIndex===examRun.questions.length-1?'disabled':''}>Siguiente</button><button class="btn btn-primary" id="examFinish">Entregar examen</button></div></section>`;
 $('#examPrev').onclick=()=>{examIndex--;drawExamQuestion()};$('#examNext').onclick=()=>{examIndex++;drawExamQuestion()};
 const save=async val=>{try{await request('/api/exams/runs/'+encodeURIComponent(examRun.run_id)+'/answers/'+encodeURIComponent(String(q.id)),{method:'PUT',body:{answer:val}});examAnswers[String(q.id)]=val;const st=$('#examSaveStatus');if(st)st.textContent='Respuesta guardada'}catch(e){toast(e.message)}};
 host.querySelectorAll('input[name=examChoice]').forEach(x=>x.onchange=()=>save(Number(x.value)));
 const numeric=$('#examValue');if(numeric)numeric.onchange=()=>save(numeric.value);
 $('#examFinish').onclick=async()=>{if(!confirm('¿Entregar el examen? No podrás modificarlo después.'))return;try{const result=await(await request('/api/exams/runs/'+encodeURIComponent(examRun.run_id)+'/finish',{method:'POST'})).json();clearInterval(examInterval);examInterval=null;host.innerHTML=`<section class="card elevate"><h1>Resultado: ${result.score}/10</h1><p>${result.correct} respuestas correctas de ${result.total}.</p><p class="muted-note">La autoevaluación es independiente de la calificación oficial. Los resultados de este examen no modifican el modelo BKT de práctica.</p>${(result.details||[]).map(d=>'<div class="pedagogic-explanation"><strong>Pregunta '+escapeHTML(d.id)+' · '+(d.correct?'Correcta':'Incorrecta')+'</strong><p>'+escapeHTML(d.explanation)+'</p></div>').join('')}<button class="btn btn-primary" id="backExams">Volver a exámenes</button></section>`;$('#backExams').onclick=()=>drawExams(false)}catch(e){toast(e.message)}};
 clearInterval(examInterval);examInterval=setInterval(()=>{const n=Math.max(0,Math.ceil((Date.parse(examRun.deadline)-Date.now())/1000));const el=$('#timerValue'),ring=$('#timerRing');if(!el){clearInterval(examInterval);return}el.textContent=fmtTime(n);const ratio=n/(Math.max(1,(Date.parse(examRun.deadline)-Date.parse(examRun.started))/1000));ring.style.setProperty('--timer-color',`hsl(${Math.round(120*ratio)} 78% 39%)`);ring.style.setProperty('--timer-deg',Math.round(ratio*360)+'deg');if(n===0){clearInterval(examInterval);request('/api/exams/runs/'+encodeURIComponent(examRun.run_id)+'/finish',{method:'POST'}).then(r=>r.json()).then(result=>{toast('Tiempo agotado. Nota: '+result.score+'/10');drawExams(false)}).catch(e=>toast(e.message))}},1000);
}
function installExamNavigation(){
 const sidebar=document.querySelector('.side-nav');if(sidebar&&!sidebar.querySelector('[data-page="exams"]')){const b=document.createElement('button');b.dataset.page='exams';b.innerHTML='<span>▤</span> Exámenes';sidebar.appendChild(b);b.onclick=()=>navigate('exams')}
 const dock=document.querySelector('.mobile-dock');if(dock&&!dock.querySelector('[data-page="exams"]')){const b=document.createElement('button');b.dataset.page='exams';b.innerHTML='<span>▤</span><small>Exámenes</small>';dock.appendChild(b);b.onclick=()=>navigate('exams')}
}
installExamNavigation();
